* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #15211e; color: #f5f2e9; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #29443a 0, #1b2c27 42%, #15211e 80%); }
button { min-height: 48px; border: 2px solid transparent; border-radius: 8px; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s ease, background-color .12s ease, border-color .12s ease, box-shadow .12s ease; }
button:hover:not(:disabled) { transform: translateY(-2px); }
button:active:not(:disabled) { transform: translateY(1px) scale(.98); }
button:focus-visible { outline: 3px solid #f5f2e9; outline-offset: 3px; }
.board { width: min(100%, 680px); padding: clamp(22px, 5vw, 42px); border: 3px solid #405c4e; border-radius: 18px; background: #20342d; box-shadow: 0 16px 50px #0a1310aa, inset 0 0 0 5px #182821; }
.board-header { text-align: center; }
.eyebrow, .period-label, .team h2, .hint { letter-spacing: .16em; font-size: 14px; font-weight: 800; }
.eyebrow { margin: 0 0 8px; color: #e4b957; }
h1 { margin: 0; font-size: clamp(24px, 5vw, 36px); line-height: 1.15; letter-spacing: .05em; }
.subtitle { margin: 10px 0 26px; color: #bdc9c0; font-size: 16px; }
.period-panel { min-height: 74px; padding: 12px 16px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border: 1px solid #456253; border-radius: 10px; background: #192a24; }
.period-label { color: #bdc9c0; }
.period-display { font-variant-numeric: tabular-nums; font-size: 25px; font-weight: 900; }
.period-divider { padding: 0 5px; color: #7c9886; }
.period-button { padding: 0 14px; color: #18251f; background: #e4b957; }
.period-button:hover:not(:disabled) { background: #f0ca72; }
.period-button:disabled { opacity: .45; cursor: not-allowed; }
.teams { position: relative; display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin: 22px 0; }
.team { min-width: 0; padding: 20px 14px 16px; text-align: center; border: 2px solid #506b5b; border-radius: 12px; background: #293f35; }
.team-amber { --accent: #e4b957; }
.team-mint { --accent: #77d4aa; }
.team-heading { display: flex; align-items: center; justify-content: center; gap: 9px; }
.team-marker { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 6px; color: #18251f; background: var(--accent); font-weight: 900; }
.team h2 { margin: 0; font-size: 16px; }
.score { display: block; margin: 14px 0 18px; color: var(--accent); font-size: clamp(58px, 12vw, 78px); font-weight: 900; line-height: 1; font-variant-numeric: tabular-nums; text-shadow: 0 4px 0 #101b16; }
.score-buttons { display: flex; gap: 8px; }
.score-buttons button { flex: 1; padding: 0 4px; color: #19251f; background: var(--accent); font-size: 18px; }
.score-buttons button:hover { filter: brightness(1.12); }
.versus { position: absolute; z-index: 1; top: 50%; left: 50%; padding: 6px; transform: translate(-50%, -50%); border-radius: 6px; color: #bdc9c0; background: #20342d; font-size: 12px; font-weight: 900; letter-spacing: .1em; }
.board-footer { display: flex; gap: 12px; }
.undo-button, .reset-button { flex: 1; padding: 0 12px; color: #f5f2e9; background: #354e42; border-color: #587363; }
.undo-button:hover:not(:disabled) { background: #456354; }
.undo-button:disabled { opacity: .45; cursor: not-allowed; }
.reset-button { color: #18251f; background: #77d4aa; border-color: #77d4aa; }
.reset-button:hover { background: #91e4bd; }
.hint { margin: 22px 0 0; text-align: center; color: #8fa898; font-size: 12px; }
@media (max-width: 440px) { body { padding: 18px 12px; } .board { padding: 22px 16px; } .teams { gap: 12px; } .team { padding: 16px 10px 12px; } .score-buttons { gap: 5px; } .score-buttons button { font-size: 16px; } .board-footer { gap: 8px; } .period-panel { padding-inline: 12px; } }

const scores = { a: 0, b: 0 };
let period = 1;
let lastChange = null;

const scoreA = document.querySelector('#score-a');
const scoreB = document.querySelector('#score-b');
const periodNumber = document.querySelector('#period-number');
const undoButton = document.querySelector('#undo');
const nextPeriodButton = document.querySelector('#next-period');

function render() {
  scoreA.textContent = String(scores.a).padStart(2, '0');
  scoreB.textContent = String(scores.b).padStart(2, '0');
  periodNumber.textContent = String(period);
  undoButton.disabled = lastChange === null;
  nextPeriodButton.disabled = period === 4;
}

document.querySelectorAll('[data-team][data-points]').forEach((button) => {
  button.addEventListener('click', () => {
    const team = button.dataset.team;
    const points = Number(button.dataset.points);
    lastChange = { team, points };
    scores[team] += points;
    render();
  });
});

undoButton.addEventListener('click', () => {
  if (lastChange === null) return;
  scores[lastChange.team] -= lastChange.points;
  lastChange = null;
  render();
});

nextPeriodButton.addEventListener('click', () => {
  if (period < 4) period += 1;
  render();
});

document.querySelector('#reset').addEventListener('click', () => {
  scores.a = 0;
  scores.b = 0;
  period = 1;
  lastChange = null;
  render();
});

render();
